// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {DepositLog} from "../src/DepositLog.sol";

contract InvMutTest is Test {
    DepositLog c;
    function setUp() public { c = new DepositLog(); }
    function testFuzz_property(address logger, bool status) public {
        // C's constructor leaves _contractOwner unset, so the owner is address(0);
        // only calls from address(0) are admissible (otherwise "Not owner" revert).
        vm.assume(logger != address(0));
        vm.prank(address(0));
        c.setApprovedLogger(logger, status);
        // General rule: an approved-logger setting at key logger is observable at that key.
        assertTrue(c.approvedLoggers(logger) == status);
    }
}
